function StoreDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            if key == 'products' then
                for i = 1, #value do
                    local dojo = StoreGoodsDojo.New()
                    dojo:Fill(value[i])
                    table.insert(self.products, dojo)
                end
                table.sort(self.products, function(a, b)
                    if a.pos ~= b.pos then
                        return a.pos < b.pos
                    else
                        return a.productId < b.productId
                    end
                end)
            elseif key == 'refreshConsume' then
                self.refreshConsume.goodsId = value.goodsId
                self.refreshConsume.num = value.num
            else
                self[key] = value
            end
        end
    end
end

function StoreDojo:Sort(token)
    if #token <= 1 then
        return
    end
    
    local weight = {}
    for i = 1, #token do
        weight[token[i]] = i
    end

    if self.products ~= nil then
        for i = 1, #self.products do
            self.products[i]:SortPrices(weight)
        end
    end
end

return StoreDojo